{"path": "proverb.py", "content": "def proverb(*items, qualifier=None):
    """Return the lines of the proverb built from the given items."""
    if not items:
        return []
    lines = [
        f"For want of a {want} the {lost} was lost."
        for want, lost in zip(items, items[1:])
    ]
    first, *_ = items
    subject = f"{qualifier} {first}" if qualifier else first
    lines.append(f"And all for the want of a {subject}.")
    return lines
